verify.cmd:
node -e 'const fs=require("fs")
const fail=(m)=>{console.error(m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return null}}
const code=(s)=>s.replace(/\/\*[\s\S]*?\*\//g," ").replace(/^\s*\/\/.*$/gm," ")

const D=rd("lib/spaces/front-door.ts")
if(D===null)fail("the Space front-door copy module is gone")
const dc=code(D)
if(/\bdefault\s*:/.test(dc))fail("spaceFrontDoor grew a default arm: a new viewer state would silently inherit another states sentence instead of failing the build")
for(const v of ["anonymous","visitor","waitlist","member"]){
  if(!new RegExp("case ."+v+".:").test(dc))fail("spaceFrontDoor has no arm for the "+v+" reader, so that person gets no sentence")
}
const armOf=(v)=>{const m=new RegExp("case ."+v+".:").exec(dc);if(!m)return null;let end=dc.length
  for(const o of ["anonymous","visitor","waitlist","member"]){const mm=new RegExp("case ."+o+".:").exec(dc);if(mm&&mm.index>m.index&&mm.index<end)end=mm.index}
  return dc.slice(m.index,end)}
const mem=armOf("member")
if(!mem)fail("could not isolate the member arm")
if(mem.indexOf("/community")<0)fail("the member door no longer points at the Space Community wall, the conversation a member was asked to be sent to (ADR-1938)")
for(const v of ["anonymous","visitor"]){const a=armOf(v)
  if(a.indexOf("plans")<0)fail("the "+v+" door stopped reaching for the Memberships tab, which is the one surface that lists the tiers and takes the money")
  if(!/tierCount === 0/.test(a))fail("the "+v+" door no longer goes quiet on a Space that publishes no tiers, so it pitches a membership that does not exist")}
const wl=armOf("waitlist")
if(/tierCount === 0/.test(wl))fail("the waitlist door now depends on the tier count, but someone already queuing is owed an answer whether or not the Space still sells")
if(wl.indexOf("action: null")<0)fail("the waitlist door offers a join action again, which re-pitches a membership to someone who already asked for one")

const P=rd("app/(public)/spaces/[slug]/page.tsx")
if(P===null)fail("the public Space page is gone")
const pc=code(P)
if(pc.indexOf("<SpaceFrontDoor")<0)fail("the ISR share URL stopped rendering the front door, so a visitor on the canonical Space link gets no pitch")
if(!/viewer="anonymous"/.test(pc))fail("the public tree passes a viewer other than anonymous: that render has no caller at all, so any other value is a claim it cannot support")
for(const bad of ["getMyMembership","getCallerProfile","getMyProfileId"]){
  if(new RegExp("\\b"+bad+"\\s*\\(").test(pc))fail("the ISR page now calls "+bad+", which makes the route dynamic and costs the share URL its cache (ADR-1465, ADR-1526)")}
if(pc.indexOf("listMembershipTiers")<0)fail("the public page no longer reads the Space tiers, so its door cannot know whether there is anything to sell")

const F=rd("app/(main)/spaces/[slug]/(profile)/full/page.tsx")
if(F===null)fail("the member Space home is gone")
const fc=code(F)
if(fc.indexOf("<SpaceFrontDoor")<0)fail("the member Space home stopped rendering the front door, so a member and a stranger get identical bodies again, which is the defect this row closed")
if(fc.indexOf("getMyMembership")<0)fail("the member home no longer reads the viewer membership, so it cannot tell a member from a visitor")
if(fc.indexOf("waitlist")<0)fail("the member home collapsed the waitlist state into visitor, so someone already queuing gets pitched the membership again")
console.log("LIVE-524 ok")'
